<script setup lang="ts">
import {computed} from 'vue';
import {LockKeyhole,ShieldCheck,AlertCircle} from 'lucide-vue-next';
type Item=Record<string,any>;
const props=defineProps<{value:Item;impact:string}>();
const removed=computed(()=>(props.value.previous?.agent_overrides??[]).filter((item:Item)=>!(props.value.proposed.agent_overrides??[]).some((next:Item)=>next.agent_id===item.agent_id)));
function protection(value:boolean){return value?'Segredo · o BI não devolve os valores':'Variável comum · valores legíveis na API do BI';}
</script>
<template><section class="variable-review"><h3><ShieldCheck :size="17"/>Configuração da variável</h3><p class="variable-reference">{{value.proposed.reference}}</p><div class="variable-comparison"><article v-if="value.previous"><strong>Atual</strong><p>{{protection(value.previous.is_secret)}}</p><p>{{value.previous.description||'Sem descrição'}}</p><p>{{value.previous.agent_overrides.length}} {{value.previous.agent_overrides.length===1?'definição':'definições'}} por agente</p></article><article><strong>{{value.previous?'Proposto':'Nova variável'}}</strong><p>{{protection(value.proposed.is_secret)}}</p><p>{{value.proposed.description||'Sem descrição'}}</p><p>{{value.proposed.agent_overrides.length}} {{value.proposed.agent_overrides.length===1?'definição':'definições'}} por agente</p></article></div><p class="variable-value-action"><LockKeyhole :size="15"/>{{value.value_action}}</p><template v-if="value.overrides_changed"><p v-if="!value.proposed.agent_overrides.length">Todos os agentes usarão o valor padrão.</p><ul v-else><li v-for="row in value.overrides" :key="row.agent_id"><strong>{{row.agent_name}}</strong> · {{row.value_action}}</li></ul><p v-if="removed.length">Remover definição dos agentes: {{removed.map((row:Item)=>'#'+row.agent_id).join(', ')}}. Eles voltarão ao valor padrão.</p></template><p v-else>As definições por agente já cadastradas serão mantidas.</p><p v-if="value.previous?.is_secret&&!value.proposed.is_secret" class="variable-disclosure"><AlertCircle :size="17"/>A proteção de segredo será removida. Os novos valores enviados poderão ser lidos pela API do BI. Os segredos anteriores não serão revelados.</p><p class="variable-impact">{{impact}}</p><p v-if="value.secret_values_submitted">O BI confirma o recebimento de segredos, mas não devolve seus valores para conferência por leitura. Uma resposta incerta não autoriza repetir o envio.</p></section></template>
<style scoped>.variable-review{font-size:12px;line-height:1.8;color:#607895;overflow-wrap:anywhere}.variable-review h3,.variable-value-action{display:flex;align-items:center;gap:8px;color:#355a8b}.variable-review h3{font-size:13px;margin:0 0 8px}.variable-reference{font-family:monospace;color:#42648f;margin-bottom:12px}.variable-comparison{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(230px,100%),1fr));gap:12px}.variable-comparison article{background:#f5f8fd;border:1px solid #e2eaf6;border-radius:8px;padding:13px;min-width:0}.variable-comparison strong{color:#344f75}.variable-comparison p{margin:7px 0 0;white-space:pre-wrap}.variable-value-action{margin:15px 0}.variable-value-action svg,.variable-disclosure svg{flex-shrink:0}.variable-review ul{padding-left:21px}.variable-review li{margin:7px 0}.variable-impact,.variable-disclosure{background:#fff8eb;border-radius:7px;padding:12px;color:#735a31;margin:14px 0}.variable-disclosure{display:flex;align-items:flex-start;gap:9px;background:#fff1e8;color:#91552f}</style>
